(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["af"] = {"ui":{"skip":"Spring na die inhoud","back":"← Terug na AI-gile","lang.button":"Taal: {name}","lang.dialog":"Kies 'n taal","lang.search":"Soek tale","lang.none":"Geen taal pas nie","lang.notYet":"{name} is nog nie vertaal nie","theme.aria":"Wissel tema: lig, donker of swart","theme.toLight":"Wissel na lig tema","theme.toDark":"Wissel na donker tema","theme.toBlack":"Wissel na swart tema (ware swart, sag op OLED-skerms)","words.underline":"Onderstreep hierdie woorde op die bladsy","words.underlineHelp":"Beweeg oor of tik op 'n gestippelde woord om te sien wat dit beteken.","words.col.todo":"Kaarte wat nou gekies is: die span begin hierdie volgende.","words.col.doing":"'n KI werk nou aan hierdie kaart.","words.col.review":"Een KI is klaar met die werk; 'n ander kyk dit na voordat dit by jou uitkom.","words.col.verify":"Wag vir jou: probeer dit uit en sê of dit werk.","words.col.team":"Jou notas of antwoorde, wat wag dat die span dit optel.","words.col.done":"Klaar en aanvaar.","index.title":"AI-gile: jou KI-ontwikkelaarspan, op een bord","index.description":"AI-gile is 'n kanban-bord vir KI-programmeerspanne. Hulle werk terwyl jy slaap; jy kry een kort hopie dinge om te besluit, te toets en te aanvaar.","hero.logoAlt":"AI-gile-bordikoon","hero.h1.html":"Jou KI-ontwikkelaarspan, op een&nbsp;bord.","hero.alpha":"🐣 Geslote pre-alfa","hero.alphaTitle":"Vroeg en onafgehandel: dankie dat jy dit probeer!","hero.lede":"Hulle bou terwyl jy slaap. Jy word wakker met een kort hopie: 'n paar vrae, 'n paar goed om te toets, een of twee pers diamante. Klik, aanvaar, terug na jou koffie.","dl.windows":"Windows-app","dl.browser":"Gebruik dit in jou blaaier","dl.messenger":"📱 Messenger vir jou foon","dl.soon":"Binnekort","dl.notify":"🔔 Laat weet my wanneer dit oopgaan","dl.notifySmall":"Alfa of beta","hero.secondary":"Agile, maar die span hoef nooit 'n stand-up-koffie te drink nie. (Hulle hou tog stand-ups.)","pitch.h2":"AI-gile in soveel woorde as jy wil","pitch.lede":"Kies 'n lengte, van een woord tot 144. Elke lengte is sy eie beskrywing, vir daardie grootte geskryf. Sleep die skuifbalk of gebruik die pyltjiesleutels.","pitch.rangeLabel":"Lengte in woorde","pitch.dice":"🎲 nog 'n weergawe","pitch.words.one":"{n} woord","pitch.words.other":"{n} woorde","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakters","count.line.html.one":"{n} kaart op die bord op die oomblik","count.line.html.other":"{n} kaarte op die bord op die oomblik","people.humans.html.one":"👥 {n} mens","people.humans.html.other":"👥 {n} mense","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agente","people.working.html.one":"⚡ {n} aan die werk op die oomblik","people.working.html.other":"⚡ {n} aan die werk op die oomblik","pre.title":"AI-gile: hier word iets gebou","pre.description":"Hier word iets gebou. 'n Bord waar KI-spanne bou wat jy vra, en jou leer terwyl hulle werk. Vir nou 'n geslote pre-alfa met vriende.","pre.h1":"Hier word iets gebou. 🤫","pre.line":"'n Bord waar KI-spanne bou wat jy vra, en jou leer terwyl hulle werk. Vir nou 'n geslote pre-alfa met vriende.","pre.btn":"🔔 Laat weet my wanneer dit oopgaan","pre.peek":"Agter die glas: die regte bord, regstreeks. Elke kaart is 'n gekleurde strook.","pre.peekFake":"Agter die glas: so lyk 'n bord wat aan die werk is.","pre.night":"🌙 Die nagwag is in beheer · 😴 die mens rus","features.aria":"Wat dit doen","f.pile.h":"Een hopie vir jou","f.pile.html":"<b>Vir jou</b> hou alles wat op jou wag, oor elke projek heen: vrae, goed om te toets, take wat net 'n mens kan doen. Jou tou sê wat volgende is en hoe lank dit neem.","f.sleep.h":"Spanne wat werk terwyl jy slaap","f.sleep.p":"Elke projek het 'n leier en 'n span KI-agente. Lewer kommentaar op 'n kaart en die span word wakker, doen die werk, en gee dit terug met stappe wat 'n moeë mens kan volg.","f.tester.h":"'n KI-toetser kyk eerste","f.tester.p":"Voordat enigiets by jou uitkom, volg 'n toetser die stappe in 'n kopie van die app en wys wat hy gesien het, met 'n skermkiekie. Blaai deur die geslaagdes en aanvaar met een klik.","f.proof.h":"Bewys, nie beloftes nie","f.proof.p":"Elke oorhandiging wys wat verander het: die lêers, die diff, die skermkiekies. Jy hoef nie elke app oop te maak om te sien of dit klaar is nie.","f.chat.h":"Gesels met jou leiers","f.chat.p":"'n Discord-agtige balk: een ikoon per projek, pers diamante vir wat jou nodig het. Stuur 'n leier 'n idee; hy maak dit kaarte en 'n plan, met 'n ✅ Gaan-knoppie.","f.tidy.h":"Hou homself netjies","f.tidy.p":"Verwante kaarte word een, deurmekaar titels word reggemaak, en 'n token-kontrole hou die kode skraal. Minder om tussen te wissel, minder om aan te dink.","f.private.h":"Joune, op jou rekenaar","f.private.li1":"Die bord loop op jou eie masjien en antwoord net vir jou.","f.private.li2":"Private DM's tussen mense is end-tot-end-geënkripteer.","f.private.li3":"Geen rekeninge, geen snuffelaars, geen koekies.","f.lang.h":"In jou taal","f.lang.p":"Meer as 120 tale, van Nederlands, Wallies en Japannees tot seerower, Yoda en Klingon, met 'n vinnige wissel terug na Engels vir die vakjargon.","f.service.h":"Van 'n idee tot 'n regte diens","f.service.p":"Iets met KI gebou wat mense nou gebruik? Merk dit as 'n diens en die bord help jou om dit goed te bedryf: beskikbaarheidskontroles, 'n openbare statusbladsy, voorvalle met 'n nabetragting, veranderings wat 'n Go nodig het, rugsteune wat daagliks nagegaan word. Hulp leer jou elke stap soos jy aangaan.","msgr.h2":"AI-gile Messenger: jou span in jou sak","msgr.p1":"Praat met jou KI-span sonder om die bord oop te maak. Klets met jou projekleiers en jou vriende, en sien 'n kaart se toetsstappe en beantwoord hulle, alles van jou foon af.","msgr.p2":"Om dit te koppel, skandeer 'n QR-kode op jou bord. Eerste keer? 'n Vriendelike demo-klets wys jou die pad.","msgr.when":"Eers Android, dan 'n webweergawe vir fone en iPhone.","msgr.who":"Jou projekleier","msgr.b1":"Die regstelling vir donkermodus is gereed. Wil jy die toetsstappe hê?","msgr.b2":"Ja asseblief!","msgr.b3":"1. Maak Instellings oop. 2. Kies Donker. Lyk dit reg?","tl.aria":"Tydlyn van die eerste gesprek tot die padkaart","tl.h2":"Van die eerste gesels tot wat volgende kom","tl.lede":"Regte datums en tye, in jou eie tydsone. Ná vandag is dit die plan, sonder beloofde datums.","tl.today":"Vandag","tl.planned":"beplan","tl.doing":"besig","tl.cards.one":"{n} kaart","tl.cards.other":"{n} kaarte","join.h2":"Doen saam","join.lede":"AI-gile word gebou deur 'n bebaarde eksentrieke ou met AuDHD en 'n paar geestesgesondheidstryde, en 'n groot klomp geduldige agente. Dit is vir eers privaat, in 'n geslote alfa met vriende. Wil jy 'n kans hê wanneer dit oopgaan?","join.btn":"Teken belangstelling in","join.small":"Ons stuur jou 'n e-pos, niks anders nie","footer.tag":"AI-gile. Geen snuffelaars, geen koekies, geen stand-up-koffie.","footer.licence":"Besigheidslisensie","footer.status":"Status","footer.privacy":"Wat ons hou","footer.thanks":"Oproepe danksy ChilledChat","form.sending":"Stuur tans…","form.failed":"Dit het nie gewerk nie: probeer later weer.","form.offline":"Kon nie AI-gile bereik nie: probeer later weer.","form.keep":"Ons gebruik dit net om jou te antwoord, en vee dit dan uit. Geen snuffelaars, geen koekies.","form.keepLink":"Wat ons hou","interest.title":"AI-gile: laat weet my wanneer die alfa oopgaan","interest.description":"Los jou e-pos om te hoor wanneer AI-gile se geslote alfa of beta oopgaan.","interest.h1":"🔔 Laat weet my wanneer dit oopgaan","interest.lede":"AI-gile is in geslote pre-alfa. Los jou e-pos en ons skryf een keer, wanneer daar 'n plek vir jou is.","interest.email":"Jou e-pos","interest.which":"Watter toets?","interest.alpha":"Geslote alfa: vroeg, rof, baie veranderinge","interest.beta":"Beta: bestendiger, later","interest.both":"Enige een, wat ook al eerste kom","interest.submit":"Sit my op die lys","interest.thanks":"Dankie! Jy is op die lys.","licence.title":"AI-gile: besigheidslisensie","licence.description":"Gebruik jy AI-gile in jou besigheid? Doen aansoek om 'n gratis besigheidslisensie.","licence.h1":"📜 Besigheidslisensie","licence.lede":"Gebruik jy AI-gile by die werk? Vertel ons wie jy is en wat jy doen. As dit 'n bietjie goed doen, is die lisensie gratis.","licence.company":"Maatskappy","licence.website":"Webwerf","licence.what":"Wat jy doen","licence.how":"Hoe dit die wêreld help","licence.email":"E-pos","licence.submit":"Doen aansoek","licence.thanks":"Dankie! Ons antwoord per e-pos.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Alles rustig","status.intro":"Werk AI-gile nou? Hierdie bladsy kyk elke 5 minute na die webwerf, borddeling, oproepe en die aflaai.","status.up":"Werk (het in {ms} ms geantwoord)","status.slow":"Het nie op die laaste kontrole geantwoord nie, probeer weer","status.down":"Af: het nie op die laaste twee kontroles geantwoord nie","status.svc.web":"Webwerf","status.svc.web.offers":"Hierdie werf: wat AI-gile is, en die belangstellingsvorm","status.svc.boards":"Borddeling","status.svc.boards.offers":"Openbare borde, boodskappe tussen vriende en uitnodigings","status.svc.calls":"Oproepe","status.svc.calls.offers":"Stem, video en skermdeling in AI-gile","status.svc.download":"Aflaai","status.svc.download.offers":"Die Windows-installeerder en uitnodigingskakels","status.checking":"Kyk tans…","status.offline":"Kan die statusdiens nou nie bereik nie (probeer weer)","status.updated":"opgedateer {ago}","status.justNow":"nou net","status.min":"{n} min gelede","status.hours":"{n} u gelede","status.days":"{n} d gelede","privacy.title":"AI-gile: wat ons hou","privacy.h1":"Wat ons hou","privacy.lede":"Kort weergawe: net wat jy vir ons stuur, en nie vir lank nie.","privacy.only":"Net wat jy vir ons stuur: wat jy in 'n vorm intik, soos jou e-pos. Niks anders oor jou nie.","privacy.sealed":"Dit word verseël sodat ons bediener dit nie kan lees nie: in jou blaaier voordat dit vertrek (op 'n ouer blaaier, die oomblik wat dit aankom). Net ons eie bord kan dit oopmaak.","privacy.server":"Dit word van die bediener uitgevee sodra dit ons bord bereik. Enigiets wat ná 30 dae nog daar is, word in elk geval uitgevee.","privacy.board":"Ons hou dit net op ons bord totdat ons jou geantwoord het, en vee dit dan daar ook uit.","privacy.none":"Geen snuffelaars, geen koekies, geen analitika.","privacy.local":"Jou taal en lig- of donkerkeuse bly in jou eie blaaier. Dit word nooit na ons gestuur nie.","privacy.ask":"Wil jy hê dit moet gouer weg wees? Antwoord op ons e-pos en sê so.","live.h2":"Kyk hoe dit gebou word, regstreeks","live.caption":"Elke kaart is versteek: jy sien die vorm van die werk, nie die woorde nie.","live.watching.one":"regstreeks: {n} kyk","live.watching.other":"regstreeks: {n} kyk","live.last.now":"Laaste kaart pas verskuif","live.last.min.one":"Laaste kaart {n} min gelede verskuif","live.last.min.other":"Laaste kaart {n} min gelede verskuif","live.last.hour.one":"Laaste kaart {n} uur gelede verskuif","live.last.hour.other":"Laaste kaart {n} uur gelede verskuif","live.last.day.one":"Laaste kaart {n} dag gelede verskuif","live.last.day.other":"Laaste kaart {n} dae gelede verskuif","live.offline":"Die lewendige bord haal asem. Kom kyk gou weer.","live.cols":"Backlog|Om te doen|Besig|Span kontroleer|Vir jou om te toets|Vir die span|Klaar"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotte.","Uitbestee."]},{"n":2,"texts":["Robotte-kanban, gratis.","Agente, georganiseer.","Idees, gebou."]},{"n":3,"texts":["Kanban vir robotte.","Idees word funksies.","Gratis agent-kanban."]},{"n":5,"texts":["Kanban-bord wat agente bestuur.","Jy skryf kaarte. Agente bou.","Gratis, plaaslik, getoets, effens simpel."]},{"n":8,"texts":["'n Gratis kanban-bord waar KI-agente werk doen.","Skryf 'n idee. Agente bou dit. Jy aanvaar.","Agile vir een mens en baie geduldige robotte."]},{"n":13,"texts":["'n Kanban-bord op jou rekenaar waar KI-agente die kaarte optel en afhandel.","Skryf 'n idee. 'n Span agente bou dit. 'n Toetser kyk dit na.","Gratis, geen rekeninge, geen snuffelaars: 'n bord, 'n paar robotte, en jy aan die stuur."]},{"n":21,"texts":["AI-gile is 'n kanban-bord om saam met KI-programmeeragente te werk. Hulle tel die kaarte op; jy toets en aanvaar dit.","Elke projek kry 'n leier en 'n span KI-agente. Lewer kommentaar op enige kaart en die span gaan aan die werk.","'n Gratis, persoonlike taakbord wat op jou eie rekenaar loop. Die werkers is robotte. Die een wat ja sê, is jy."]},{"n":34,"texts":["Jy sit idees op 'n bord. 'n Span KI-agente maak daarvan werkende funksies, toets dit, en gee dit terug met stappe om te probeer. Niks tel as klaar totdat jy dit sê nie.","AI-gile is 'n tuisgemaakte kanban-bord wat Rich gebou het met baie hulp van die agente wat dit nou bestuur. Dit is gratis, loop op jou rekenaar, en word met vriende gedeel, nie verkoop nie.","Dink aan 'n gewone kanban-bord, met kolomme van Backlog tot Klaar, behalwe dat KI-agente die kaarte optel. Hulle rapporteer vordering, vra vrae as hulle vassit, en wag altyd vir jou duim in die lug."]},{"n":55,"texts":["AI-gile is 'n kanban-bord waar die span uit KI-agente bestaan. Elke projek het 'n leier wat die werk beplan en helpers wat dit bou. Wanneer 'n funksie gereed is, probeer 'n KI-toetser dit en neem 'n skermkiekie, dan beland dit in jou hopie. Aanvaar dit, of lewer kommentaar en hulle werk dit oor.","Dit het begin as een persoon se manier om baie KI-programmeersessies gelyktydig dop te hou, en het gegroei tot 'n regte bord. Dit loop op jou masjien, vra geen rekening nie, en het geen snuffelaars nie. Dit is gratis vir vriende en enigeen wat nuuskierig is. Dit is ook onafgehandel, so verwag rowwe kante en die af en toe verrassing.","Hier is die eerlike weergawe. Jy moet steeds die idees hê, en jy moet steeds die resultate nagaan. Wat AI-gile doen, is alles tussenin: dit hou die kaarte in orde, wek die regte agent wanneer jy kommentaar lewer, wys presies wat verander het, en hou alles in een kort hopie vir jou."]},{"n":89,"texts":["AI-gile is 'n gratis kanban-bord wat jy op jou eie rekenaar laat loop. In plaas van mense het elke projek 'n span KI-agente: 'n leier wat jou idees in kaarte en 'n plan omskep, en helpers wat die kaarte in volgorde van prioriteit optel. Wanneer iets gebou is, volg 'n KI-toetser die toetsstappe en wys jou wat hy gesien het. Dan wag dit in een hopie gemerk Vir jou. Jy aanvaar dit, of jy lewer kommentaar en die span probeer weer. Niks kom ooit by Klaar uit sonder jou nie.","Party funksies verwag jy dalk nie. 'n Nagwag hou die kolom Om te doen aangevul terwyl jy slaap, en kies kaarte wat nie 'n antwoord van jou nodig het nie. 'n Tokenteller wys hoeveel die agente vandag en hierdie week gebruik het, en Geen-Token-Modus sê vir hulle om op te hou spandeer. Jy kan vriende boodskappe stuur, en private boodskappe is end-tot-end-geënkripteer. Die bord praat sowat 120 tale, onder andere Nederlands, Vlaams, seerower en Klingon. Niks daarvan kos 'n sent nie, en niemand probeer dit ook vir jou verkoop nie.","AI-gile is 'n klein, persoonlike projek, nie 'n maatskappy nie. Rich wou na etlike KI-programmeerprojekte omsien sonder om elke app oop te maak om daarna te kyk, so hy en die agente het 'n bord daarvoor gebou, en toe die bord gebruik om die res van homself te bou. Dit is in geslote pre-alfa, wat beteken dit werk, meestal, vir 'n handjievol vriende. Daar is geen pryslys, geen nuusbrief en geen groeiplan nie. As dit nuttig klink, kan jy vra om dit te probeer wanneer dit 'n bietjie verder oopgaan."]},{"n":144,"texts":["AI-gile is 'n kanban-bord vir een mens en 'n klomp KI-agente. Dit loop op jou eie rekenaar en dit is heeltemal gratis. Jy voeg projekte by, en elke projek kry 'n leier en 'n klein span. Jy gesels met die leier, 'n bietjie soos op Discord, en beskryf 'n idee; die leier maak dit kaarte en 'n plan, en wag dan dat jy Gaan druk. Die span werk die kaarte in volgorde van prioriteit af, met 'n eenvoudige opdragreël wat vir taalmodelle gemaak is. Voordat enigiets na jou terugkom, volg 'n KI-toetser die stappe in 'n kopie van die app en heg 'n skermkiekie aan. Klaargemaakte werk beland in jou hopie met die veranderde lêers en die diff. Jy aanvaar dit, of jy los 'n kommentaar en die span word wakker en probeer weer. Net jy kan 'n kaart na Klaar skuif.","'n Dag met AI-gile, ongeveer. In die aand los jy 'n paar kommentare: hierdie knoppie is op die verkeerde plek, daardie lys moet gesorteer wees, kan ons 'n donker modus kry. Jy gaan slaap. Die agente lees die kommentare, maak die veranderinge, toets dit en gee dit aan jou terug. As Om te doen leegloop, vul die nagwag dit uit die backlog met kaarte wat geen antwoord van jou nodig het nie. In die oggend is daar een kort hopie: 'n paar vrae en 'n paar goed om te probeer, elk met stappe wat 'n slaperige mens kan volg en 'n skermkiekie wat wys dit werk. Jy klik deur, aanvaar die goeies en stuur die res terug. 'n Tokenteller wys wat alles gebruik het, en Geen-Token-Modus is daar vir maer weke. Dan eet jy ontbyt, waarmee die agente nog nie kan help nie.","Eerstens, wat AI-gile nie is nie. Dit is nie 'n begin-maatskappy nie, dit is nie te koop nie, en niemand versamel jou data nie. Dit is 'n gratis bord wat op jou rekenaar loop, sonder rekeninge, snuffelaars of koekies. Wat dit wel is: een netjiese plek om elke KI-programmeerprojek gelyktydig te sien, met 'n span agente wat die kaarte doen en jy wat die besluite neem. Dit voeg verwante kaarte saam, maak deurmekaar titels reg, en hou dop hoe skraal die kode bly. Dit praat sowat 120 tale, van Nederlands en Vlaams tot seerower en Klingon. Vriende kan mekaar boodskappe stuur, privaat en geënkripteer. Dit is gebou deur Rich en 'n groot klomp geduldige agente, meestal deur homself te gebruik. Dit is in geslote pre-alfa, so dit is op plekke rof. As dit na pret klink, vra mooi en jy kan dalk vroeg inkom."]}],"quips":{"1":"Een woord. Gewaagd. Dalk te gewaagd.","3":"Drie woorde. Reeds eerliker as die meeste produkbladsye.","8":"Agt woorde. Steeds korter as 'n stand-up.","21":"Die lengtes is storiepunte, terloops. Natuurlik is hulle.","55":"Vyf-en-vyftig woorde. Twee kaarte is klaar terwyl jy dit gelees het.","144":"Dis die lang een. Daar is geen 233 nie. Die agente is gaan slaap."}},"timeline":{"first-idea.name":"Die eerste idee","first-idea.line":"Die allereerste gesprek, voordat daar enige kode was.","first-board.name":"Eerste bord","first-board.line":"'n Bord wat sy eie bou naspoor: kaarte, kolomme, sleep-en-los, projekte.","team-roles.name":"Span en rolle","team-roles.line":"Agentprofiele, spansjablone, ruimtes en wie wat doen.","install.name":"Installeer en weergawes","install.line":"'n Zip wat 'n vriend kan installeer, selfopdatering, kanale en terugrol.","usage-saver.name":"Gebruiksbespaarder","usage-saver.line":"Meet wat lopies kos, hou die kode skraal, spaar jou limiet.","friends.name":"Vriende en deel","friends.line":"Private DM's, 'n versleutelde relay, uitnodigings, rolle en gedeelde projekte.","languages.name":"Tale","languages.line":"Elke skermteks in 'n taallêer, met Nederlands en Vlaams eerste.","ai-tester.name":"KI-toetser","ai-tester.line":"'n Toetser kyk elke oorhandiging eerste na en wys wat hy gesien het.","website.name":"Die webwerf","website.line":"aigile.lol, die teaser en hierdie tydlyn.","streaming.name":"Klets en stroming","streaming.line":"Discord, Twitch, OBS, stroomermodus, GIF's en emoji's.","no-ai.name":"Sonder-KI-uitgawe","no-ai.line":"'n Bord vir mense wat sonder KI programmeer, en openbare borde.","night-watch.name":"Nagwag","night-watch.line":"'n Wag en Scrum Master hou die spanne op koers terwyl jy slaap.","p-more.name":"Alles anders","p-more.line":"Kleiner idees wat nog op hul beurt wag.","p-android.name":"Foon en Android","p-android.line":"Bereik jou bord vanaf 'n foon, dan 'n eie Android-app.","p-release.name":"Alfa en verder","p-release.line":"Geslote alfa, die lewendige werf, dan beta.","p-languages.name":"Meer tale","p-languages.line":"130 tale, en 'n onderdompelingsmodus vir leerders.","p-engines.name":"Meer KI-enjins","p-engines.line":"Kies Claude, Codex, Gemini, Copilot of Cursor per agent.","p-pro.name":"Professionele praktyk","p-pro.line":"Risikoetikette, samevoegpoorte, voorvalkaarte en leuningrelings.","p-self.name":"Na jou omsien","p-self.line":"Moeë-modus, selfsorg-herinnerings en 4:20.","p-servers.name":"Bedieners en skaal","p-servers.line":"Globale bedienerinstellings, rolle en beplanning vir groei.","p-livestream.name":"Stroom-ekstras","p-livestream.line":"Twitch-klets, eie emoji's en 'n openbare regstreekse blik."},"words":{"button":"📖 Vakjargon","h":"📖 Woorde verduidelik","intro":"Die woorde wat jy in AI-gile teëkom, in gewone taal: dit bou, dit veilig verander, dit aan die gang hou vir die mense wat dit gebruik, en as 'n span saam met KI werk.","search":"Soek 'n woord…","none":"Geen woord stem daarmee ooreen nie.","close":"Maak toe","count":{"one":"{count} woord","other":"{count} woorde"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Dit bou"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Dit veilig verander"},{"id":"run","name":"🛎️ 'n Diens bedryf"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have.","also":["feasible"]},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["prioritising","prioritise","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Idees en werk wat nog nie ingeskeduleer is nie. Daar word aan niks gewerk voordat dit na Om te doen skuif nie."},{"id":"sprint","g":"agile","word":"Sprint","text":"'n Kort tydperk van werk (dikwels 'n week of twee) met 'n ooreengekome stel kaarte om klaar te maak.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"'n Vinnige inskakeling: wat elke spanlid gedoen het, wat hulle volgende doen, en wat hulle terughou.","also":["standup","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"'n Bord met kolomme (Om te doen, Besig, Klaar) waar kaarte van links na regs skuif soos werk gebeur."},{"id":"wip","g":"agile","word":"WIP-limiet","text":"Work in progress: die hoogste aantal kaarte wat 'n kolom mag hou, sodat die span dinge klaarmaak voor hulle meer begin.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definisie van Klaar","text":"Die span se kort kontrolelys van wat “klaar” beteken, soos getoets en verduidelik, voordat 'n kaart aan jou oorhandig word. Sy tweeling, die Definisie van Gereed, sê wanneer 'n kaart duidelik genoeg is om te begin.","also":["Definisie van Gereed","Definition of Done","Definition of Ready"]},{"id":"retro","g":"agile","word":"Terugblik","text":"'n Terugblik op hoe die span werk, om ooreen te kom oor een ding om beter te doen. In AI-gile stel 'n terugblik 'n verandering aan die span se werkswyse voor, en jy sê Gaan of Nog nie.","also":["terugblikke","retro","retrospektief"]},{"id":"swarm","g":"agile","word":"Swerm","text":"Alle hande aan dek: elke span los ander werk om op een dringende projek te help totdat dit uitgesorteer is. Ander projekte wag intussen.","also":["swerm","swarm"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Die een wat die werk aan die vloei hou: sien vasgehaakte kaarte raak, por die spanne aan en herinner jou aan wat wag. In AI-gile doen die Lead Scrum Master dit oor elke projek.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["SAFe","scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Die projek se gids met kode en sy volle geskiedenis van commits, gewoonlik ook op GitHub gehou.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"'n Aparte werklyn in die kode, sodat veranderinge gemaak kan word sonder om aan die hoofweergawe te raak.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"'n Gestoorde kiekie van die kode, met 'n kort nota van wat verander het. Jy kan altyd na een teruggaan.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Gestoorde kiekies (commits) van hierdie rekenaar na GitHub stuur, sodat hulle 'n rugsteun het en gedeel word."},{"id":"merge","g":"build","word":"Merge","text":"Die veranderinge van 'n branch weer by die hoofweergawe voeg."},{"id":"pr","g":"build","word":"Pull request","text":"Vra dat 'n branch se veranderinge nagegaan en by die hoofweergawe saamgevoeg word.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Die kode opruim sonder om te verander wat dit doen: kleiner lêers, duideliker name, minder herhaling."},{"id":"bug","g":"build","word":"Bug","text":"Iets wat nie werk soos dit moet nie.","also":["bugs","fout","foute"]},{"id":"peerreview","g":"build","word":"Portuurhersiening","text":"'n Tweede paar oë: 'n ander KI kyk elke kaart se werk na voordat dit by jou uitkom, sodat minder foute deurglip.","also":["kodehersiening","peer review","code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor.","also":["responsive"]},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiled","compiler","compiling"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Toets","text":"'n Voltooide stuk werk uitprobeer om seker te maak dit doen wat gevra is, voordat jy dit aanvaar.","also":["toetse","test","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kort vir quality assurance (gehalteversekering): die outomatiese kontroles wat loop voordat enigiets regstreeks gaan. As QA rooi is, het iets misluk, en dit kan nie regstreeks gaan voordat dit reggemaak is nie.","also":["gehaltebeheer","kwaliteitskontrole","KW"]},{"id":"testpile","g":"test","word":"Toetsstapel","text":"Die klaar kaarte wat wag dat jy hulle probeer, een na die ander. Aanvaar een of stuur dit terug met 'n nota, en die volgende een kom op.","also":["toetsstapels"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["coverage","code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"'n Nuwe weergawe aanlyn sit, byvoorbeeld op 'n bediener waar mense dit gebruik."},{"id":"release","g":"change","word":"Vrystelling","text":"'n Benoemde bondel klaar werk wat saam regstreeks gaan, met kort notas oor wat verander het. 🚀 Vrystellings skryf die notas uit die klaar kaarte.","also":["vrystellings","release"]},{"id":"rollback","g":"change","word":"Rol terug","text":"Teruggaan na die laaste weergawe wat gewerk het as 'n nuwe een moeilikheid gee. In AI-gile maak dit 'n kontrolelys van die ontdoen-stappe wat op elke verandering geskryf is.","also":["terugrol","teruggerol","rollback"]},{"id":"live","g":"change","word":"Regstreeks","text":"Die regte weergawe wat mense gebruik, anders as 'n kopie om dinge op uit te probeer. Ontwikkelaars noem dit ook produksie.","also":["produksie","live"],"noTip":1},{"id":"change","g":"change","word":"Verandering","text":"'n Beplande verandering aan iets waarop mense staatmaak, eers neergeskryf: wat, hoekom, die risiko, wanneer, en hoe om dit te ontdoen. Begin een met 🔀 Dien 'n verandering in.","also":["veranderings","veranderingsversoek","change"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Iets wat kan skeefloop, met 'n telling vir hoe waarskynlik en hoe erg dit sou wees. ⚠️ Risiko's hou hulle in een lys, hoogste telling eerste, elk met 'n datum om weer te kyk.","also":["risiko's","risikoregister"]},{"id":"chgwin","g":"change","word":"Veranderingsvenster","text":"Die tye wanneer veranderings regstreeks mag gaan, soos 'n stil Dinsdagaand. Buite 'n venster kan 'n veranderingskaart nie klaargemaak word nie, tensy dit 'n noodgeval is.","also":["veranderingsvensters","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"'n Vinnige stemming net voordat 'n verandering regstreeks gaan: elke persoon wat moet goedkeur, sê Go of No go. Dit gaan net voort as hulle saamstem.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Goedkeuring","text":"Wag vir 'n ja voordat werk begin. 'n Kaart wat 'n vriend indien, of 'n verandering, wag in ✅ Goedkeurings totdat jy dit goedkeur of afkeur.","also":["goedkeurings"]},{"id":"quiettime","g":"change","word":"Stil tyd","text":"'n Tydperk, soos 'n stroom, 'n demo of die nag, wanneer niks regstreeks gaan nie. Die spanne werk en toets verder, maar regstreeks gaan wag totdat dit verby is. Elders word dit 'n veranderingsbevriesing genoem.","also":["stil tye","veranderingsbevriesing","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company.","also":["hosted"]},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Diens","text":"Iets wat jy gebou het waarop mense staatmaak, soos 'n webwerf of 'n toep, wat opgepas word sodat dit aanhou werk. Merk “Hierdie projek is 'n diens” en sê wat dit bied, wie dit gebruik en wie op diens is.","also":["dienste"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Beskikbaarheidskontrole","text":"'n Outomatiese kontrole, elke paar minute, dat jou diens nog antwoord. As dit 'n paar keer na mekaar misluk, maak AI-gile self 'n voorvalkaart oop.","also":["beskikbaarheid","uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Statusbladsy","text":"'n Openbare bladsy wat wys of 'n diens werk (groen, oranje of rooi) met die jongste nuus, sodat die mense wat dit gebruik kan kyk in plaas van vra.","also":["statusbladsye","status page"]},{"id":"desk","g":"run","word":"Dienslessenaar","text":"Waar vrae en berigte van die mense wat jou diens gebruik, inkom. AI-gile sorteer elkeen as 'n versoek, 'n voorval of 'n idee, en sê so as dit lyk na iets wat reeds aangemeld is.","also":["dienslessenaars","hulplessenaar","hulptoonbank"]},{"id":"svcrequest","g":"run","word":"Diensversoek","text":"Iemand wat vra vir iets gewoons, soos 'n nuwe rekening of 'n bietjie hulp, eerder as om te sê dat iets stukkend is. Dit wag sy beurt; 'n voorval gaan eerste.","also":["diensversoeke"]},{"id":"incident","g":"run","word":"Voorval","text":"Iets wat nou stukkend is vir die mense wat dit gebruik, soos die webwerf wat af is. 'n 🔥 Voorvalkaart spring die tou: om dit weer aan die werk te kry kom eerste.","also":["voorvalle","incident"]},{"id":"major","g":"run","word":"Groot voorval","text":"'n Groot voorval: baie mense geraak, of geld of data in gevaar. Een knoppie sit elke span daarop (swerm), maak wakker wie ook al op diens is en vra elke 30 minute vir 'n statusopdatering.","also":["groot voorvalle","major incident"]},{"id":"oncall","g":"run","word":"Op diens","text":"Die een wees wat antwoord as iets breek, selfs in die nag. Elke diens het 'n spanlid op diens wat eerste wakker gemaak word vir sy voorvalle.","also":["diensbeurt","bystand","on call"]},{"id":"replyby","g":"run","word":"Antwoordtyd","text":"Hoe lank 'n kaart mag wag vir 'n eerste antwoord, byvoorbeeld 'n uur vir 'n voorval. Daarna kry dit 'n rooi horlosie, sodat niks stilletjies vergeet word nie. Ook 'n antwoordteiken genoem.","also":["antwoordtye","antwoordteiken","antwoordteikens"]},{"id":"postmortem","g":"run","word":"Nabetragting","text":"'n Kort terugblik na 'n voorval: wat gebeur het, wat gehelp het en wat om te verander, sonder om iemand te blameer. 'n Voorval kan nie sonder een gesluit word nie.","also":["nabetragtings","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Probleem","text":"Die verborge oorsaak agter een of meer voorvalle. 'n 🧩 Probleemkaart groepeer voorvalle wat aanhou terugkom, sodat die oorsaak gevind en vir goed reggemaak word.","also":["probleme"],"noTip":1},{"id":"rootcause","g":"run","word":"Grondoorsaak","text":"Die ware rede waarom iets gebreek het, nie net wat jy sien skeefloop het nie. Maak die grondoorsaak reg en die voorval hou op terugkom.","also":["grondoorsake","root cause"]},{"id":"workaround","g":"run","word":"Tydelike oplossing","text":"'n Manier om dinge aan die werk te hou totdat die regte oplossing gereed is, soos om iets te herbegin as dit vashaak. Dit word op die probleemkaart geskryf sodat niemand dit weer hoef uit te werk nie.","also":["tydelike oplossings","noodoplossing","workaround"]},{"id":"knownerror","g":"run","word":"Bekende fout","text":"'n Probleem waarvan die oorsaak verstaan word en wat 'n tydelike oplossing het, maar nog nie reggemaak is nie. 🧩 Bekende foute lys hulle, sodat almal die tydelike oplossing gebruik in plaas van weer te grawe.","also":["bekende foute","known error"]},{"id":"runbook","g":"run","word":"Draaiboek","text":"Stap-vir-stap-instruksies om 'n bekende soort moeilikheid reg te maak, sodat dit elke keer vinnig op dieselfde manier gedoen word. Na 'n groot voorval kan die span een voorstel wat jy kan goedkeur.","also":["draaiboeke","runbook"]},{"id":"ci","g":"run","word":"Konfigurasie-item","text":"Een ding waarop jou diens staatmaak, soos 'n bediener, 'n domein, 'n sertifikaat, 'n sleutel of 'n verskaffer. 🗂️ Konfigurasie-items lys hulle per diens, sodat jy kan sien wat 'n voorval raak en wat hernu of gerugsteun moet word.","also":["konfigurasie-items"]},{"id":"expiry","g":"run","word":"Vervaldatum","text":"AI-gile hou datums dop, soos wanneer 'n sertifikaat of 'n domein verval. Binne 30 dae voor die datum maak dit een kaart om dit te hernu, sodat niks onverwags ophou werk nie.","also":["vervaldatums","verval","vervaldatumwag"]},{"id":"backup","g":"run","word":"Rugsteun","text":"'n Gestoorde kopie van jou data van vroeër, om op terug te val as iets verlore raak of beskadig word. AI-gile maak elke dag 'n rugsteun van jou borde.","also":["rugsteune","backup"]},{"id":"restore","g":"run","word":"Herstel","text":"Data uit 'n rugsteun terugsit. 'n Rugsteun tel eers regtig as jy weet dit kan herstel word, so dit is die moeite werd om dit af en toe te probeer.","also":["herstel","teruggesit","restore"]},{"id":"svcreview","g":"run","word":"Dienshersiening","text":"'n Terugblik op een maand van 'n diens: voorvalle oopgemaak en opgelos, hoe vinnig mense 'n antwoord gekry het, beskikbaarheid en tokens gebruik. Die Maandelikse hersiening wys dit vir elke diens.","also":["dienshersienings","maandelikse hersiening","maandelikse hersienings"]},{"id":"accessreview","g":"run","word":"Toegangsondersoek","text":"Elke 90 dae nagaan wie nog kan inkom: deelskakels, vriende se rolle en gestoorde geheime. Jy hou of verwyder elkeen, sodat ou toegang nie bly hang nie.","also":["toegangsondersoeke"]},{"id":"improvements","g":"run","word":"Verbeteringslys","text":"Alles waarin die span besluit het om beter te word, op een plek: terugblikvoorstelle, hersieningsaksies en probleemoplossings, elk met sy status. Vind dit onder 📈 Verbeterings.","also":["verbeteringslyste","verbeterings"]},{"id":"tokencap","g":"run","word":"Tokenlimiet","text":"'n Maandelikse limiet op die tokens wat 'n diens se agente mag gebruik. By 80% kry jy 'n waarskuwing; by 100% wag hul agtergrondwerk tot volgende maand of totdat jy die limiet verhoog.","also":["tokenlimiete"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day.","also":["managing a service"]},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice.","also":["monitored"]},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing.","also":["lag"]},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first line","second line","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service.","also":["redundant"]},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers","hand over"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal.","also":["virus","viruses"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"'n KI wat self aan 'n taak werk: lees die kode, maak veranderinge, voer kontroles uit, en rapporteer terug.","also":["agents","agente"]},{"id":"token","g":"ai","word":"Token","text":"Die eenheid waarin KI-gebruik getel word: min of meer 'n paar letters teks gelees of geskryf. Minder tokens, meer van jou plan oor.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"'n Klein opdrag wat self op 'n bepaalde oomblik loop, bv. wanneer 'n KI-sessie begin, sodat die span jou kommentaar hoor.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results.","also":["prompting"]},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals","evaluations"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers.","also":["purchasing"]},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
